#!/usr/bin/env node
'use strict';

/**
 * Read-only M3 projection gate.
 *
 * Both generations are written to detached temporary directories. The gate
 * validates the first output, proves byte determinism against a second output,
 * and then compares generated bytes with the committed projection. It never
 * regenerates a tracked artifact as a side effect of testing.
 */

const fs = require('fs');
const os = require('os');
const path = require('path');
const { spawnSync } = require('child_process');

const semanticOnly = process.argv.includes('--semantic-only');
const ROOT = path.join(__dirname, '..', '..');
const META_DIR = path.join(ROOT, 'ontology', 'meta');
const COMMITTED = path.join(META_DIR, 'projection');
const FILES = [
  'axiolune-meta.owl.ttl',
  'axiolune-meta.shacl.ttl',
  'axiolune-meta.shacl-sparql.ttl',
];

function run(script, outputDir) {
  const result = spawnSync(process.execPath, [path.join(ROOT, script)], {
    cwd: ROOT,
    env: {
      ...process.env,
      META_DIR,
      META_PROJECTION_DIR: outputDir,
    },
    encoding: 'utf8',
  });
  if (result.status !== 0) {
    process.stderr.write(result.stdout || '');
    process.stderr.write(result.stderr || '');
    throw new Error(`${script} exited ${result.status}`);
  }
  process.stdout.write(result.stdout || '');
}

function sameBytes(left, right) {
  return fs.existsSync(left) && fs.existsSync(right) &&
    fs.readFileSync(left).equals(fs.readFileSync(right));
}

const first = fs.mkdtempSync(path.join(os.tmpdir(), 'axiolune-meta-projection-a-'));
const second = fs.mkdtempSync(path.join(os.tmpdir(), 'axiolune-meta-projection-b-'));
let failed = 0;
try {
  for (const outputDir of [first, second]) {
    run('scripts/meta/generate-owl.js', outputDir);
    run('scripts/meta/generate-shacl.js', outputDir);
  }
  run('scripts/meta/test-projection.js', first);

  if (semanticOnly) {
    console.log('PASS semantic-only projection gate (parse/validate; byte drift checks skipped)');
    process.exit(0);
  }

  for (const file of FILES) {
    if (!sameBytes(path.join(first, file), path.join(second, file))) {
      console.error(`FAIL nondeterministic projection: ${file}`);
      failed++;
    } else {
      console.log(`PASS deterministic projection: ${file}`);
    }
    if (!sameBytes(path.join(first, file), path.join(COMMITTED, file))) {
      console.error(`FAIL committed projection drift: ${file}`);
      failed++;
    } else {
      console.log(`PASS committed projection matches: ${file}`);
    }
  }
} catch (error) {
  console.error(`FAIL projection gate: ${error.message}`);
  failed++;
} finally {
  fs.rmSync(first, { recursive: true, force: true });
  fs.rmSync(second, { recursive: true, force: true });
}

if (failed) process.exit(1);
console.log('PASS read-only projection gate');
